import os, base64
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
d = P("static/downloads")
if not os.path.exists(P("static/js/tour.js")): raise SystemExit("[loi] can cai patch34 truoc")
if os.path.exists(P("static/js/reveal.js")): raise SystemExit("[loi] da ap dung patch35 roi")
open(os.path.join(d, "intro.mp4"), "wb").write(base64.b64decode(""))
open(os.path.join(d, "intro-poster.jpg"), "wb").write(base64.b64decode(""))
w("static/js/tour.js", '''"use strict";
/* tour.js - hai video: Giới thiệu (kiểu keynote) và Giao diện. Tự phát khi cuộn tới, có nút tạm dừng */
(function () {
  var v = document.getElementById("tour-vid"), b = document.getElementById("tour-btn"), box = document.querySelector(".tour-in");
  if (!v || !b) return;
  var paused = false, still = window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;
  var SRC = { intro: ["/static/downloads/intro.mp4", "/static/downloads/intro-poster.jpg", "828 / 1720"], tour: ["/static/downloads/tour.mp4", "/static/downloads/tour-poster.jpg", "828 / 1900"] };
  function label() { b.textContent = v.paused ? "Phát" : "Tạm dừng"; }
  function pick(k) {
    var s = SRC[k]; if (!s) return;
    Array.prototype.forEach.call(document.querySelectorAll(".tour-tab"), function (t) { var on = t.dataset.k === k; t.classList.toggle("on", on); t.setAttribute("aria-selected", on ? "true" : "false"); });
    box.style.aspectRatio = s[2]; v.poster = s[1]; v.src = s[0]; v.load(); paused = false;
    v.play().catch(function () {}); setTimeout(label, 150);
  }
  Array.prototype.forEach.call(document.querySelectorAll(".tour-tab"), function (t) { t.addEventListener("click", function () { pick(t.dataset.k); }); });
  b.addEventListener("click", function () { if (v.paused) { paused = false; v.play().catch(function () {}); } else { paused = true; v.pause(); } label(); });
  if ("IntersectionObserver" in window) {
    new IntersectionObserver(function (es) {
      es.forEach(function (e) { if (e.isIntersecting && !paused && !still) v.play().catch(function () {}); else v.pause(); label(); });
    }, { threshold: 0.45 }).observe(v);
  }
  label();
})();
''')
w("static/js/reveal.js", '''"use strict";
/* reveal.js - thẻ tính năng, bảng so sánh, câu hỏi tung lên khi cuộn tới (kiểu keynote) */
(function () {
  if (!("IntersectionObserver" in window) || (window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches)) return;
  var items = document.querySelectorAll(".grid > article, .dl-card, .compare tbody tr, .faq details, .facts > div, h2");
  var io = new IntersectionObserver(function (es) {
    es.forEach(function (e) {
      if (!e.isIntersecting) return;
      var n = e.target, i = Array.prototype.indexOf.call(n.parentNode.children, n);
      n.style.transitionDelay = Math.min(i, 8) * 55 + "ms";
      n.classList.add("rv-in"); io.unobserve(n);
    });
  }, { threshold: 0.12 });
  Array.prototype.forEach.call(items, function (n) { n.classList.add("rv"); io.observe(n); });
})();
''')
w("static/landing.css", rd("static/landing.css") + """
.rv { opacity: 0; transform: translateY(46px) scale(.9); transition: opacity .5s ease, transform .75s cubic-bezier(.34, 1.56, .64, 1); will-change: transform, opacity; }
.rv.rv-in { opacity: 1; transform: none; }
.tour-in { aspect-ratio: 828 / 1720; }
.tour-tabs { display: inline-flex; gap: 6px; padding: 4px; border-radius: 999px; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.12); margin-top: 14px; }
.tour-tab { padding: 8px 18px; border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 14px; font-weight: 600; border: 0; cursor: pointer; }
.tour-tab.on { background: var(--gold, #e2b04a); color: #1a1408; }
""")
L = rd("templates/landing.html")
L = sub(L, '<h2>Xem giao diện app</h2>\n      <p class="sub">Một vòng nhanh: camera, đăng bài, bảng tin, chat, thống kê và thư viện.</p>',
        '<h2>Xem LockCOC hoạt động</h2>\n      <p class="sub">Chọn bản giới thiệu ngắn hoặc một vòng xem giao diện thật.</p>\n      <div class="tour-tabs" role="tablist"><button class="tour-tab on" type="button" role="tab" data-k="intro" aria-selected="true">Giới thiệu</button><button class="tour-tab" type="button" role="tab" data-k="tour" aria-selected="false">Giao diện</button></div>', "tieu de")
L = sub(L, 'poster="/static/downloads/tour-poster.jpg"', 'poster="/static/downloads/intro-poster.jpg"', "poster")
L = sub(L, '<source src="/static/downloads/tour.mp4" type="video/mp4">', '<source src="/static/downloads/intro.mp4" type="video/mp4">', "src")
L = sub(L, '<div class="tour-in">', '<div class="tour-in" style="aspect-ratio:828/1720">', "ar") if False else L
L = sub(L, '  <script src="/static/js/tour.js"></script>', '  <script src="/static/js/tour.js"></script>\n  <script src="/static/js/reveal.js"></script>', "script")
w("templates/landing.html", L)
print("[ok] patch35 xong: video keynote + hieu ung tung len")
